func recordJSON(r *relayproof.Record) jsonRecord {
	return jsonRecord{
		ID: r.Msg.Message.ID, Status: r.Status, Reason: r.Reason,
		Attempts: r.Attempts, NextRetry: r.NextRetry, ExpiresAt: r.Msg.ExpiresAt,
