546	// A payloadB64 entry must decode unambiguously: an entry carrying both payload
547	// and payloadB64, or an undecodable payloadB64, is an inconsistent record no
548	// build writes and rejects the directory as corrupt, leaving every byte
549	// untouched.
550	//
551	// Presence is judged by key, not by value: "payload":"" is a legal empty
552	// payload on its own, but together with any payloadB64 it is two
553	// representations at once — both values non-empty, either one empty, both
554	// empty, or the two decoding to the very same bytes all conflict, and field
555	// order does not matter. Every such record below is complete and
556	// checksum-valid and sits at the end of the log, so it must be rejected as
557	// corruption, never dropped as a torn tail or read back by picking either
558	// representation.
559	func TestPayloadB64InconsistentRecordsRejected(t *testing.T) {
560		// Struct-built cases: omitempty drops an empty Payload, so the non-empty
561		// plain clash and the undecodable base64 can use the typed entry.
562		structEntries := map[string]*logEntry{
563			"both payload and payloadB64": {
564				T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
565				Payload: "x", PayloadB64: "eA==", ProofAt: 10,
566			},
567			"undecodable payloadB64": {
568				T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
569				PayloadB64: "!!!not-base64!!!", ProofAt: 10,
570			},
571		}
572		// Raw-JSON cases: the "payload":"" key must literally be present, which the
573		// omitempty struct tag would erase on marshal.
574		rawPayloads := map[string]string{
575			"empty payload plus payloadB64 of 0xff":              `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"","payloadB64":"/w=="}`,
576			"empty payload plus empty payloadB64, equal decoded": `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"","payloadB64":""}`,
577			"non-empty payload plus empty payloadB64":            `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"x","payloadB64":""}`,
578			"plain and payloadB64 decode to the same bytes":      `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"eA==","payload":"x"}`,
579			"both representations, base64 key first":             `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"/w==","payload":""}`,
580		}
581		for name, e := range structEntries {
582			t.Run(name, func(t *testing.T) {
583				dir := t.TempDir()
584				var raw []byte
585				raw = append(raw, logMagic...)
586				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
587				raw = append(raw, encodeFrame(mustMarshal(e))...)
588				writeRawLog(t, dir, raw)
589				assertCorruptAndUntouched(t, dir, raw)
590			})
591		}
592		for name, payload := range rawPayloads {
593			t.Run(name, func(t *testing.T) {
594				dir := t.TempDir()
595				var raw []byte
596				raw = append(raw, logMagic...)
597				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
598				raw = append(raw, encodeFrame([]byte(payload))...)
599				writeRawLog(t, dir, raw)
600				assertCorruptAndUntouched(t, dir, raw)
601			})
602		}
603	}
