605	// The empty payload keeps its long-standing meaning through every legal
606	// on-disk shape, and a sole payloadB64 still restores its bytes: the new
607	// presence-based clash check must never mistake an omitted key for an
608	// empty-but-present one. Only payload:"" (the shape this build writes), both
609	// keys absent (a historical record), a sole empty payloadB64 all restore the
610	// empty payload, and a sole non-empty payloadB64 restores its exact bytes; the
611	// restored content then participates in the ordinary same-id comparison.
612	func TestPayloadEmptyOmittedAndSoleB64StillAccepted(t *testing.T) {
613		payFF := string([]byte{0xFF})
614		cases := map[string]struct {
615			payload     string
616			wantPayload string
617			badResubmit string
618		}{
619			"explicit empty payload": {
620				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":""}`,
621				wantPayload: "",
622				badResubmit: "x",
623			},
624			"both payload keys omitted (historical empty payload)": {
625				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10}`,
626				wantPayload: "",
627				badResubmit: "x",
628			},
629			"sole empty payloadB64 is the empty payload": {
630				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":""}`,
631				wantPayload: "",
632				badResubmit: "x",
633			},
634			"sole payloadB64 restores its bytes": {
635				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"/w=="}`,
636				wantPayload: payFF,
637				badResubmit: "",
638			},
639		}
640		for name, tc := range cases {
641			t.Run(name, func(t *testing.T) {
642				dir := t.TempDir()
643				var raw []byte
644				raw = append(raw, logMagic...)
645				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
646				raw = append(raw, encodeFrame([]byte(tc.payload))...)
647				writeRawLog(t, dir, raw)
648	
649				q := reopen(t, dir)
650				defer q.Close()
651				got, ok := q.Query("m")
652				if !ok {
653					t.Fatal("restored message missing")
654				}
655				if !bytes.Equal([]byte(got.Payload), []byte(tc.wantPayload)) {
656					t.Fatalf("restored payload = % x, want % x", got.Payload, tc.wantPayload)
657				}
658				// A byte-identical resubmit returns the existing record; a differing
659				// payload conflicts, proving the restored bytes are the real content.
660				same := Envelope{Message: Message{
661					ID: "m", From: "a", To: "b", Nonce: 1,
662					Payload: tc.wantPayload, ProofAt: 10,
663				}}
664				if echo, err := q.Submit(same); err != nil || echo.Msg.Message.Payload != tc.wantPayload {
665					t.Fatalf("identical resubmit of restored payload: echo=%+v err=%v", echo, err)
666				}
667				diff := same
668				diff.Message.Payload = tc.badResubmit
669				if _, err := q.Submit(diff); !errors.Is(err, ErrConflict) {
670					t.Fatalf("different content must conflict with restored payload % x: %v", tc.wantPayload, err)
671				}
672			})
673		}
674	}
675	
676	// A complete dual-payload submit record is corruption even when perfectly
677	// good records precede it — including the submit entry a compaction writes to
678	// restore an already processed message, followed by its state entry. Open
679	// refuses the whole directory with ErrCorrupt, returns no usable queue and
680	// leaves the complete offending frame (and everything before it)
681	// byte-for-byte in place, so none of the earlier normal messages can be
682	// queried either.
683	func TestPayloadDualRepresentationRejectedAfterNormalRecordsAndInSnapshot(t *testing.T) {
684		t.Run("normal submit then dual-payload final record", func(t *testing.T) {
685			dir := t.TempDir()
686			var raw []byte
687			raw = append(raw, logMagic...)
688			raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
689			raw = append(raw, encodeFrame(mustMarshal(&logEntry{
690				T: kindSubmit, Seq: 0, ID: "ok", From: "a", To: "b", Nonce: 1,
691				Payload: "normal", ProofAt: 10,
692			}))...)
693			raw = append(raw, encodeFrame([]byte(
694				`{"t":"submit","seq":1,"id":"bad","from":"a","to":"b","nonce":2,"proofAt":10,"payload":"","payloadB64":"/w=="}`))...)
695			writeRawLog(t, dir, raw)
696			assertCorruptAndUntouched(t, dir, raw)
697		})
698	
699		t.Run("dual-payload submit in a compacted snapshot with its state", func(t *testing.T) {
700			dir := t.TempDir()
701			var raw []byte
702			raw = append(raw, logMagic...)
703			raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
704			// This is the submit/state ordering compact() writes to restore a
705			// delivered message; the dual-payload submit must reject the snapshot.
706			raw = append(raw, encodeFrame([]byte(
707				`{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"","payloadB64":"/w=="}`))...)
708			raw = append(raw, encodeFrame(mustMarshal(&logEntry{
709				T: kindState, Now: 1000, ID: "m", Status: StatusSuccess, Attempts: 1,
710				ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
711			}))...)
712			writeRawLog(t, dir, raw)
713			assertCorruptAndUntouched(t, dir, raw)
714		})
715	}
