// writeRawLog creates queue.log in dir with exactly the given bytes.
func writeRawLog(t *testing.T, dir string, data []byte) string {
	t.Helper()
	path := filepath.Join(dir, logName)
	if err := os.WriteFile(path, data, 0o600); err != nil {
